create or replace function public.save_event(payload jsonb) returns public.events language plpgsql security invoker set search_path=public as $$declare v_id uuid;v_old events;v_result events;v_revision integer;v_member jsonb;begin if not public.is_admin() then raise exception 'admin required' using errcode='42501';end if;if payload->>'id' is null or payload->>'id'='' then insert into events(title,event_year,event_month,event_day,date_precision,date_text,category_id,summary,content,location,importance,is_featured,created_by,updated_by) values(payload#>>'{event,title}',(payload#>>'{event,event_year}')::integer,nullif(payload#>>'{event,event_month}','')::integer,nullif(payload#>>'{event,event_day}','')::integer,payload#>>'{event,date_precision}',nullif(payload#>>'{event,date_text}',''),(payload#>>'{event,category_id}')::uuid,coalesce(payload#>>'{event,summary}',''),nullif(payload#>>'{event,content}',''),nullif(payload#>>'{event,location}',''),(payload#>>'{event,importance}')::smallint,coalesce((payload#>>'{event,is_featured}')::boolean,false),auth.uid(),auth.uid()) returning id into v_id;else v_id=(payload->>'id')::uuid;select * into v_old from events where id=v_id for update;if not found then raise exception 'event not found';end if;select coalesce(max(revision_number),0)+1 into v_revision from event_revisions where event_id=v_id;insert into event_revisions(event_id,revision_number,snapshot,edited_by) values(v_id,v_revision,jsonb_build_object('event',to_jsonb(v_old)-array['id','created_at','updated_at','created_by','updated_by'],'members',coalesce((select jsonb_agg(to_jsonb(em)-array['id','event_id','created_at']) from event_members em where event_id=v_id),'[]'::jsonb)),auth.uid());update events set title=payload#>>'{event,title}',event_year=(payload#>>'{event,event_year}')::integer,event_month=nullif(payload#>>'{event,event_month}','')::integer,event_day=nullif(payload#>>'{event,event_day}','')::integer,date_precision=payload#>>'{event,date_precision}',date_text=nullif(payload#>>'{event,date_text}',''),category_id=(payload#>>'{event,category_id}')::uuid,summary=coalesce(payload#>>'{event,summary}',''),content=nullif(payload#>>'{event,content}',''),location=nullif(payload#>>'{event,location}',''),importance=(payload#>>'{event,importance}')::smallint,is_featured=coalesce((payload#>>'{event,is_featured}')::boolean,false),updated_by=auth.uid() where id=v_id;delete from event_members where event_id=v_id;end if;for v_member in select * from jsonb_array_elements(coalesce(payload->'members','[]'::jsonb)) loop insert into event_members(event_id,member_id,role,note) values(v_id,(v_member->>'member_id')::uuid,nullif(v_member->>'role',''),nullif(v_member->>'note',''));end loop;select * into v_result from events where id=v_id;return v_result;end$$;grant execute on function public.save_event(jsonb) to authenticated;
